import { readFileSync } from 'node:fs';
const input: string = readFileSync(0, 'utf8');
type Command = 'up' | 'down' | 'left' | 'right';
const COMMANDS: readonly string[] = ['up', 'down', 'left', 'right'];

function isCommand(x: string): x is Command {
  return COMMANDS.includes(x);
}

let x = 0;
let y = 0;
for (const word of input.trim().split(/\s+/)) {
  if (!isCommand(word)) {
    console.log(`ignored: ${word}`);
    continue;
  }
  if (word === 'up') y++;
  else if (word === 'down') y--;
  else if (word === 'left') x--;
  else x++;
}
console.log(`position: (${x}, ${y})`);

