import { readFileSync } from 'node:fs';
const input: string = readFileSync(0, 'utf8');
type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'rect'; width: number; height: number }
  | { kind: 'triangle'; base: number; height: number };

function assertNever(x: never): never {
  throw new Error(`Unknown shape: ${JSON.stringify(x)}`);
}

function area(s: Shape): number {
  switch (s.kind) {
    case 'circle':
      return Math.PI * s.radius ** 2;
    case 'rect':
      return s.width * s.height;
    case 'triangle':
      return (s.base * s.height) / 2;
    default:
      return assertNever(s);
  }
}

function parse(line: string): Shape {
  const [kind, a, b] = line.trim().split(/\s+/);
  if (kind === 'circle') return { kind, radius: Number(a) };
  if (kind === 'rect') return { kind, width: Number(a), height: Number(b) };
  return { kind: 'triangle', base: Number(a), height: Number(b) };
}

let best: Shape | null = null;
let bestArea = -1;
for (const line of input.trim().split('\n')) {
  const shape = parse(line);
  const a = area(shape);
  console.log(`${shape.kind}: ${a.toFixed(2)}`);
  if (a > bestArea) {
    bestArea = a;
    best = shape;
  }
}
if (best) console.log(`largest: ${best.kind}`);

