  m: 1,
  km: 1000,
  in: 0.0254,
  ft: 0.3048,
};
type Unit = keyof typeof TO_METERS;

function isUnit(x: string): x is Unit {
  return Object.hasOwn(TO_METERS, x);
}

function convert(value: number, from: Unit, to: Unit): number {
  return (value * TO_METERS[from]) / TO_METERS[to];
}

