  if (!isUnit(from)) {
    console.log(`unknown unit: ${from}`);
  } else if (!isUnit(to)) {
    console.log(`unknown unit: ${to}`);
  } else {
    const result = Number(convert(Number(v), from, to).toFixed(4));
    console.log(`${v} ${from} = ${result} ${to}`);
  }
}

