import { readFileSync } from 'node:fs';
const input: string = readFileSync(0, 'utf8');
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function validateAge(text: string): Promise<Result<number>> {
  await wait(5);
  const n = Number(text);
  if (text === '' || Number.isNaN(n)) return { ok: false, error: 'not a number' };
  if (!Number.isInteger(n) || n < 0 || n > 150) return { ok: false, error: 'out of range' };
  return { ok: true, value: n };
}

async function main(): Promise<void> {
  const lines = input.trim().split('\n').map((l) => l.trim());
  const results = await Promise.all(lines.map(validateAge));
  let valid = 0;
  results.forEach((r, i) => {
    if (r.ok) {
      valid++;
      console.log(`${lines[i]}: valid`);
    } else {
      console.log(`${lines[i]}: ${r.error}`);
    }
  });
  console.log(`valid count: ${valid}`);
}

main();

