import { readFileSync } from 'node:fs';
const input: string = readFileSync(0, 'utf8');
type Priority = 'low' | 'medium' | 'high';
interface Task {
  readonly id: number;
  title: string;
  priority: Priority;
  done: boolean;
}

const RANK: Record<Priority, number> = { high: 0, medium: 1, low: 2 };
const tasks: Task[] = [];

function isPriority(x: string): x is Priority {
  return Object.hasOwn(RANK, x);
}

for (const line of input.trim().split('\n')) {
  const [cmd, arg, ...rest] = line.trim().split(/\s+/);
  if (cmd === 'add') {
    if (!isPriority(arg)) {
      console.log(`invalid priority: ${arg}`);
      continue;
    }
    tasks.push({ id: tasks.length + 1, title: rest.join(' '), priority: arg, done: false });
  } else if (cmd === 'done') {
    const task = tasks.find((t) => t.id === Number(arg));
    if (task) task.done = true;
    else console.log(`no task ${arg}`);
  }
}

const open = tasks
  .filter((t) => !t.done)
  .sort((a, b) => RANK[a.priority] - RANK[b.priority] || a.id - b.id);
for (const t of open) {
  console.log(`#${t.id} [${t.priority}] ${t.title}`);
}
console.log(`done: ${tasks.filter((t) => t.done).length}/${tasks.length}`);
